class InvalidScoreError(ValueError):
    pass

def parse_score(raw):
    try:
        score = int(raw)
    except ValueError as error:
        raise InvalidScoreError("Ожидалось целое число") from error
    if not 0 <= score <= 100:
        raise InvalidScoreError("Оценка вне диапазона")
    return score

