import (
  "context"
  "net/http"
  "time"
)

func newServer(mux http.Handler) *http.Server {
  return &http.Server{
    Addr: ":8080",
    Handler: mux,
    ReadHeaderTimeout: 5 * time.Second,
    IdleTimeout: 60 * time.Second,
  }
}

func serve(server *http.Server, stop <-chan struct{}) error {
  listenErr := make(chan error, 1)
  go func() { listenErr <- server.ListenAndServe() }()
  select {
  case err := <-listenErr:
    if err != nil && err != http.ErrServerClosed { return err }
    return nil
  case <-stop:
    ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
    defer cancel()
    return server.Shutdown(ctx)
  }
}

