func listTasks(ctx context.Context, db *sql.DB, ownerID int64) ([]Task, error) {
  rows, err := db.QueryContext(ctx,
    "SELECT id, title FROM tasks WHERE owner_id = $1", ownerID)
  if err != nil { return nil, err }
  defer rows.Close()
  tasks := make([]Task, 0)
  for rows.Next() {
    var task Task
    if err := rows.Scan(&task.ID, &task.Title); err != nil { return nil, err }
    tasks = append(tasks, task)
  }
  if err := rows.Err(); err != nil { return nil, err }
  return tasks, nil
}

